const b = $json.body ?? $json;
const surface = String(b.surface || '').trim().toLowerCase();
const conversation_id = String(b.conversation_id || b.conversationId || '').trim();
const comment_id = String(b.comment_id || b.commentId || '').trim();
// The comment's own timestamp, not now: the 7-day window is measured from it.
const inbound_at = String(b.inbound_at || b.timestamp || b.created_time || '').trim();
const tier = String(b.tier || 'free').trim().toLowerCase();
const page_ref = String(b.page_ref || b.page || 'unknown_page').trim();
const kind = b.kind === 'reply' ? 'reply' : 'private_reply';
const allowed = ['facebook','instagram','tiktok'];
const why = !allowed.includes(surface) ? `surface ${surface || '(none)'} has no Chatfuel DM`
  : !conversation_id ? 'no conversation_id — a DM is a reply, not a broadcast'
  : !inbound_at ? 'no inbound_at — the messaging window cannot be proven'
  : kind === 'private_reply' && !comment_id ? 'no comment_id — one private reply per comment'
  : null;
return [{ json: { valid: why === null, why, surface, conversation_id, comment_id, inbound_at, tier, page_ref, kind } }];

